corrections=[]
def C(kind,pages,title,body,chapter,refs):corrections.append(dict(kind=kind,pages=pages,title=title,body=body,chapter=chapter,refs=refs))
C('补充条件','37','正交不等于条件均值为零','E[Xu]=0 比 E[u|X]=0 弱。总体正交结合大样本条件可支持一致性，不能单独保证有限样本无偏。解释性质时要分别列出所用假设。','ch03',['ols','mit'])
C('订正','74','双侧 p 值也要对观测统计量取绝对值','双侧检验计算 P(|T|≥|t_obs|)，不能在观测 t 为负时直接使用 P(|T|>t_obs)。对称连续分布下等于 2[1−F(|t_obs|)]。显著性水平应预先确定。','ch04',['ols'])
C('补充条件','42、74、84','未拒绝不等于接受为真','小概率事件仍会发生。拒绝原假设存在第一类错误；未拒绝可能来自证据不足或检验功效较低，并不证明原假设成立。','ch04',['mit'])
C('补充条件','99','VIF 阈值不是模型选择的裁决','VIF=10 是经验参考而非普适检验临界值。不要为使系数显著而反复删变量，尤其不要删去识别所需的混杂变量。','ch09',['ols'])
C('补充条件','104','异方差检验的参考分布','BP、White 的 LM 检验通常使用渐近卡方分布；辅助回归的 F 形式不能一概解释为任意小样本下的精确 F 检验。需核对误差分布及所选实现。','ch10',['ols'])
C('术语澄清','106','协方差矩阵与标准误','稳健协方差矩阵包含多个系数的方差及协方差；单个系数的标准误是对应对角元素的平方根，不是整个矩阵。','ch10',['ols'])
C('订正','115','过度识别检验的判断方向','在工具有效及模型其余设定正确的联合原假设下，显著拒绝才提示联合限制存在问题；不显著不能证明工具有效。恰好识别时没有多余限制可供该检验。','ch11',['iv'])
C('补充条件','125','序列相关下的 OLS 性质有前提','误差自相关不必然使 OLS 有偏，但无偏或一致仍依赖适当外生性。含滞后因变量且误差相关时可能连正交条件也失败。AR(1) 的相关一般不只发生在相邻一期。','ch13',['time','ols'])
C('订正','132','随机游走的均值不必发散','无漂移随机游走 y_t=y_(t−1)+ε_t，固定初值、零均值独立冲击下，E[y_t]=y_0；Var(y_t)=tσ² 随时间增加。非平稳来自方差变化，不要求均值发散。','ch14',['time'])
C('补充条件','124、131','弱平稳不是所有极限定理的充分条件','仅均值和协方差结构不随时间改变，不足以自动得到 LLN 或 CLT。还需遍历性、适当弱依赖、矩条件等；具体定理的条件可能不同。','ch14',['mit'])
C('补充条件','135–143','单位根检验依赖确定性项与滞后设定','ADF 的原假设是单位根；不拒绝不等于证实单位根。截距、趋势与滞后长度影响检验，不能把普通 t 临界值直接搬过来。','ch14',['adf'])
C('订正','145–146','协整不自动恢复普通回归推断','协整回归的超一致性并不保证通常的 t、F 推断有效。Engle–Granger 残差检验需使用适配协整检验的临界值，而非一般 ADF 临界值。','ch15',['coint'])
C('补充条件','149','误差修正速度与稳定性','调整系数应结合完整动态系统判断。在简单无其他动态的偏离模型中，稳定要求 |1+λ|<1，即 −2<λ<0；−1<λ<0 对应不振荡收敛的一种情形。ECM 不保证样本外预测总是更好。','ch15',['time'])
C('订正','156','Granger 预测关系不能替代结构因果判断','Granger 检验关注在给定信息集与滞后设定下，一组过去值能否增加预测信息。它不是一般结构因果效应的充分条件，也不应被说成所有因果关系的普遍必要条件。','ch16',['granger'])
C('补充条件','174、176','个体固定效应与时间固定效应分开看','个体 FE 吸收个体内时间不变变量。只有时间变化、个体间相同的变量可以进入单向个体 FE；加入完整时间效应后才会被吸收。','ch20',['panel'])
glossary=[]
for term,en,definition,ch in [
('估计目标','Estimand','研究想识别的总体量；要写明对象、干预及比较。',1),('潜在结果','Potential outcomes','同一对象在不同处理状态下可能出现的结果。',1),('重叠性','Overlap','在相关协变量取值下，两种处理状态都有正概率。',1),('条件期望','Conditional expectation','给定信息后的总体平均，不是某一个体的确定结果。',2),('均值独立','Mean independence','条件均值不随条件变量改变，比不相关更强。',2),('正交条件','Orthogonality','变量与误差乘积的总体期望为零。',3),('残差','Residual','观测结果与拟合值的样本差。',3),('误差','Error term','总体模型中未由解释部分描述的结果成分。',3),('BLUE','Best linear unbiased estimator','给定假设下在线性无偏估计量类中方差最小。',3),('标准误','Standard error','估计量抽样标准差的估计。',4),('p 值','p-value','原假设模型下获得至少同样极端统计量的概率。',4),('置信区间','Confidence interval','重复抽样中按固定程序构造的区间覆盖真值的比例有标称水平。',4),('预测区间','Prediction interval','针对新观测而非仅条件均值，包含个体噪声。',4),('满列秩','Full column rank','解释变量列之间不存在精确线性依赖。',5),('投影','Projection','将结果分解为解释变量张成空间内的拟合部分与正交残差。',5),('半弹性','Semi-elasticity','水平变量变动一个单位对应结果对数的变化。',6),('FWL 定理','Frisch–Waugh–Lovell','先剔除其他控制变量的线性部分，可恢复指定系数。',7),('联合检验','Joint test','同时检验多个参数限制。',7),('一致性','Consistency','样本量增长时估计量依概率趋近目标参数。',8),('渐进正态','Asymptotic normality','适当中心化缩放后的估计量极限分布为正态。',8),('共线性','Multicollinearity','解释变量间存在精确或近似线性关系。',9),('异方差','Heteroskedasticity','误差条件方差随解释变量或观测对象改变。',10),('WLS','Weighted least squares','给残差平方赋予权重；有效权重通常与条件方差成反比。',10),('内生性','Endogeneity','回归解释变量与结构误差之间存在违背识别要求的关系。',11),('排除限制','Exclusion restriction','工具变量不经被工具化变量之外的途径直接影响结果。',11),('弱工具','Weak instruments','工具与内生变量的条件关联过弱，常规近似可能失效。',11),('严格外生性','Strict exogeneity','给定解释变量所有时期的信息，当前误差条件均值为零。',12),('HAC','Heteroskedasticity and autocorrelation consistent','在适当条件下应对异方差和时间相关的协方差估计。',13),('聚类标准误','Cluster-robust SE','允许群内相关，依赖适当群间独立与足够群数等条件。',13),('弱平稳','Weak stationarity','均值恒定，有限方差且协方差只随时间间隔变化。',14),('单位根','Unit root','自回归多项式含单位根，冲击可能具有持续影响。',14),('协整','Cointegration','若干非平稳序列的非零线性组合是平稳的。',15),('误差修正','Error correction','让短期变化响应上一期偏离长期关系的程度。',15),('Granger 预测关系','Granger causality','过去值在给定信息集下改善预测的关系。',16),('极大似然','Maximum likelihood','把观测数据固定，选择令其似然最大的参数。',17),('优势比','Odds ratio','两种状态下 p/(1−p) 的比值，不是概率差。',18),('边际效应','Marginal effect','解释变量的小变化对目标条件均值或概率的局部影响。',18),('删失','Censoring','对象保留，超过阈值的真实结果被阈值等信息替代。',19),('截断','Truncation','符合特定范围的对象才进入可观测样本。',19),('固定效应','Fixed effects','以个体等维度的效应吸收对应层面不变因素。',20)]:glossary.append(dict(term=term,en=en,definition=definition,chapter=f'ch{ch:02}'))
